class SyncEngine:
    def __init__(self):
        self._lock = threading.RLock()
        self._version = 0
        self._clients: Dict[str, int] = {}  # user_id -> last_seen_version
        self._changes: List[Dict[str, Any]] = []

    def apply_change(self, change: Dict[str, Any]) -> int:
        """Apply a change and return the new version number."""
        with self._lock:
            self._version += 1
            change["version"] = self._version
            change["timestamp"] = datetime.utcnow().isoformat()
            self._changes.append(change)
            return self._version

    def get_changes_since(self, user_id: str, since_version: int) -> List[Dict[str, Any]]:
        """Get changes since a given version for a specific user."""
        with self._lock:
            self._clients[user_id] = max(self._clients.get(user_id, 0), since_version)
            return [
                change for change in self._changes
                if change["version"] > since_version
            ]

    def get_current_version(self) -> int:
        return self._version

