class FeedbackEngine:
    def __init__(self):
        self._patterns = {
            "over_spent": "You've exceeded your {category} budget by ${amount:.2f}. Consider reducing discretionary spending or reallocating funds.",
            "under_spent": "You've only used {percent:.1f}% of your {category} budget. You could consider increasing savings or shifting funds to an over-spent category.",
            "trend_warning": "Your {category} spending has increased by {percent:.1f}% compared to last month. Review your habits.",
            "goal_progress": "You're {percent:.1f}% toward your {goal_name} goal. Keep it up!"
        }

    def analyze_budget(self, categories: Dict[str, BudgetCategory]) -> List[Dict[str, Any]]:
        """Generate feedback based on budget status."""
        feedback = []
        for cat_id, cat in categories.items():
            if cat.allocated > 0:
                usage = cat.usage_percent
                if usage > 100:
                    feedback.append({
                        "type": "over_spent",
                        "category": cat.name,
                        "amount": abs(cat.remaining),
                        "message": self._patterns["over_spent"].format(
                            category=cat.name, amount=abs(cat.remaining)
                        )
                    })
                elif usage > 90:
                    feedback.append({
                        "type": "warning",
                        "category": cat.name,
                        "percent": usage,
                        "message": f"You're at {usage:.1f}% of your {cat.name} budget. Watch your spending!"
                    })
                elif usage < 30:
                    feedback.append({
                        "type": "under_spent",
                        "category": cat.name,
                        "percent": usage,
                        "message": self._patterns["under_spent"].format(
                            category=cat.name, percent=usage
                        )
                    })
        return feedback

    def analyze_goals(self, goals: List[FinancialGoal]) -> List[Dict[str, Any]]:
        """Generate goal-related feedback."""
        feedback = []
        for goal in goals:
            if not goal.completed and goal.progress_percent >= 75:
                feedback.append({
                    "type": "goal_progress",
                    "goal_name": goal.name,
                    "percent": goal.progress_percent,
                    "message": self._patterns["goal_progress"].format(
                        goal_name=goal.name, percent=goal.progress_percent
                    )
                })
        return feedback

